import React, { useEffect, useState } from "react";
import UsageGraph from "./GraphUsage";
import GenStats from "./GenStats";
import PokemonBuildPanel from "./buildPanel";

const POKE_PATH = "/pokemon_data/";

const images = require.context(
  "../public/pokemon_artwork",
  false,
  /\.jpg$/
);

const imageSet = new Set(
  images.keys().map((key) =>
    key.replace("./", "").replace(".jpg", "")
  )
);

export default function ComUsage() {
  const [pokemonList, setPokemonList] = useState([]);
  const [filteredList, setFilteredList] = useState([]);
  const [search, setSearch] = useState("");
  const [selectedPokemon, setSelectedPokemon] = useState(null);
  const [compareList, setCompareList] = useState([]);
  const [selectedGen, setSelectedGen] = useState("9");
  const [battleMode, setBattleMode] = useState("doubles");
  const [clickedBuild, setClickedBuild] = useState(null);
  const [viewMode, setViewMode] = useState("usage");
  const [filterOpen, setFilterOpen] = useState(true);

  const normalize = (str) =>
    str?.toLowerCase().replace(/[^a-z0-9]/g, "") || "";

  const formatName = (name) =>
    name
      ?.toLowerCase()
      .replace(/[^a-z0-9\s-]/g, "")
      .trim()
      .replace(/\s+/g, "-");

  const getImage = (name) =>
    `/pokemon_artwork/${formatName(name)}.jpg`;

  const loadCSV = async (path) => {
    const res = await fetch(path);
    return await res.text();
  };

  const parseCSV = (text) =>
    text
      .trim()
      .split("\n")
      .slice(1)
      .map((r) =>
        r.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/)
      );

  useEffect(() => {
    setViewMode("usage");
  }, []);

  useEffect(() => {
    const loadData = async () => {
      const text = await loadCSV(
        POKE_PATH + "pokemon_smogon_names.csv"
      );

      const rows = parseCSV(text);

      const list = rows.map((row) => ({
        display: row[0],
        smogon: row[1],
      }));

      const valid = list.filter((p) =>
        imageSet.has(formatName(p.display))
      );

      setPokemonList(valid);
      setFilteredList(valid);
    };

    loadData();
  }, []);

  useEffect(() => {
    const filtered = pokemonList.filter((p) =>
      normalize(p.display).includes(normalize(search))
    );

    setFilteredList(filtered);

    if (filtered.length === 1) {
      setSelectedPokemon(filtered[0]);
    }
  }, [search, pokemonList]);

  const addToCompare = () => {
    if (
      selectedPokemon &&
      !compareList.find(
        (p) => p.display === selectedPokemon.display
      )
    ) {
      setCompareList([...compareList, selectedPokemon]);
    }
  };

  const removePokemon = (name) => {
    setCompareList(compareList.filter((p) => p.display !== name));
  };

  return (
    <div>
      <div style={{ padding: 15, background: "#f5f5f5" }}>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: "15px",
            flexWrap: "wrap",
            marginBottom: "10px",
            background: "#eaeaea",
            padding: "8px",
            borderRadius: "8px",
          }}
        >


          <div>
            <label>Battle Mode: </label>
            <select
              value={battleMode}
              onChange={(e) =>
                setBattleMode(e.target.value)
              }
            >
              <option value="singles">Singles</option>
              <option value="doubles">Doubles</option>

            </select>
          </div>

          <div>
            <label>Generation: </label>
            <select
              value={selectedGen}
              onChange={(e) =>
                setSelectedGen(e.target.value)
              }
            >
              {[5, 6, 7, 8, 9].map((g) => (
                <option key={g} value={g}>
                  Gen {g}
                </option>
              ))}
            </select>
          </div>

          <div>
            <label>View: </label>
            <select
              value={viewMode}
              onChange={(e) =>
                setViewMode(e.target.value)
              }
            >
              <option value="usage">Usage Graph</option>
              <option value="stats">Stats Chart</option>
            </select>
          </div>

        </div>

        {filterOpen && (
          <>
            <div style={{ maxHeight: 150, overflowY: "auto" }}>
              {filteredList.map((p) => (
                <div
                  key={p.display}
                  onClick={() => setSelectedPokemon(p)}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 8,
                    padding: 4,
                    cursor: "pointer",
                    fontSize: "14px",
                    background:
                      selectedPokemon?.display === p.display
                        ? "#ddd"
                        : "transparent",
                  }}
                >
                  <img
                    src={getImage(p.display)}
                    alt={p.display}
                    style={{
                      width: 22,
                      height: 22,
                      objectFit: "contain",
                    }}
                  />
                  {p.display}
                </div>
              ))}
            </div>

            <br />

            <button onClick={addToCompare}>
              Add to Compare
            </button>

            <hr />

            {compareList.map((p) => (
              <div
                key={p.display}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  marginBottom: 5,
                }}
              >
                <img
                  src={getImage(p.display)}
                  alt={p.display}
                  style={{ width: 20 }}
                />
                {p.display}
                <button
                  onClick={() =>
                    removePokemon(p.display)
                  }
                >
                  X
                </button>
              </div>
            ))}
          </>
        )}

        <div style={{ textAlign: "center", marginTop: 8 }}>
          <button onClick={() => setFilterOpen(!filterOpen)}>
            {filterOpen ? "Hide Filter ▲" : "Show Filter ▼"}
          </button>
        </div>
      </div>

      <div style={{ display: "flex", gap: 30, marginTop: 20 }}>
        <div style={{ flex: 1 }}>
          {viewMode === "usage" ? (
            <UsageGraph
              compareList={compareList}
              selectedGen={selectedGen}
              battleMode={battleMode}
              onPointClick={setClickedBuild}
            />
          ) : (
            <GenStats compareList={compareList} />
          )}
        </div>

        <div style={{ width: 350 }}>
          <PokemonBuildPanel
            clickedBuild={clickedBuild}
            battleMode={battleMode}
          />
        </div>
      </div>
    </div>
  );
}
